#include <vector>
#include <deque>
using namespace std;

class Solution {
public:
    vector<int> maxSlidingWindow(vector<int>& nums, int k) {
        vector<int> result;
        deque<int> dq; // stores indices

        // Process first k elements
        for (int i = 0; i < k; i++) {
            // Remove elements smaller than current element from back
            while (!dq.empty() && nums[dq.back()] <= nums[i]) {
                dq.pop_back();
            }
            dq.push_back(i);
        }

        // Add maximum of first window
        result.push_back(nums[dq.front()]);

        // Process remaining elements
        for (int i = k; i < nums.size(); i++) {
            // Remove elements outside the current window
            while (!dq.empty() && dq.front() <= i - k) {
                dq.pop_front();
            }

            // Remove elements smaller than current element from back
            while (!dq.empty() && nums[dq.back()] <= nums[i]) {
                dq.pop_back();
            }

            dq.push_back(i);
            result.push_back(nums[dq.front()]);
        }

        return result;
    }
};
```

**How it works:**

1. **Deque Approach**: We use a deque to store indices of array elements in decreasing order of their values.

2. **Key Properties**:
   - The front of deque always contains the index of maximum element in current window
   - Elements in deque are maintained in decreasing order of their values
   - We only store indices that could potentially be maximum in future windows

3. **Algorithm Steps**:
   - Initialize deque and process first k elements
   - For each new element:
     - Remove indices that are out of current window
     - Remove indices whose corresponding values are smaller than current element
     - Add current index to deque
     - Record the maximum (front of deque)

**Time Complexity**: O(n) - each element is added and removed at most once
**Space Complexity**: O(k) - for the deque storing at most k elements

